// ═══ STATE TRANSITIONS ═══
//
// NEW ──start()──→ RUNNABLE ──run() ends──→ TERMINATED
//                     ↑  ↓
//            ┌────────┘  └────────────┐
//            │                        │
//   lock acquired              trying to enter
//            │                synchronized block
//            │                        │
//        RUNNABLE ←──── BLOCKED ──────┘
//            ↑  ↓
//   notify/  │  │  wait()/join()/park()
//   unpark   │  │
//            │  ↓
//        WAITING (indefinite)
//            ↑  ↓
//   timeout/ │  │  sleep(ms)/wait(ms)/join(ms)
//   notify   │  │
//            │  ↓
//     TIMED_WAITING

// ═══ DEMONSTRATING EACH STATE ═══
Thread t = new Thread(() -> { /* task */ });
t.getState();  // NEW — created, not started

t.start();
t.getState();  // RUNNABLE — running or ready to run

// Inside synchronized block when lock held by another:
// t.getState();  // BLOCKED — waiting for monitor lock

// After calling wait():
// t.getState();  // WAITING — waiting for notify()

// After calling Thread.sleep(5000):
// t.getState();  // TIMED_WAITING — sleeping for 5 seconds

t.join();  // wait for t to finish
t.getState();  // TERMINATED — run() completed

// ═══ CANNOT RESTART ═══
// t.start();  → IllegalThreadStateException!
// Thread is TERMINATED — cannot go back to NEW.
// Must create: Thread t2 = new Thread(sameRunnable);

// ═══ Thread.State enum ═══
// Thread.State.NEW
// Thread.State.RUNNABLE
// Thread.State.BLOCKED
// Thread.State.WAITING
// Thread.State.TIMED_WAITING
// Thread.State.TERMINATED
