// ─── File: src/test/java/com/bank/lifecycle/ThreadLifecycleTest.java ───
package com.bank.lifecycle;

import org.junit.jupiter.api.Test;
import java.util.concurrent.CountDownLatch;
import static org.assertj.core.api.Assertions.*;

class ThreadLifecycleTest {

    // ═══ NEW state ═══
    @Test
    void newState_beforeStart() {
        Thread t = new Thread(() -> {});
        assertThat(t.getState()).isEqualTo(Thread.State.NEW);
    }

    // ═══ TERMINATED state ═══
    @Test
    void terminatedState_afterCompletion() throws InterruptedException {
        Thread t = new Thread(() -> {});
        t.start();
        t.join();
        assertThat(t.getState()).isEqualTo(Thread.State.TERMINATED);
    }

    // ═══ Cannot restart terminated thread ═══
    @Test
    void cannotRestart_terminatedThread() throws InterruptedException {
        Thread t = new Thread(() -> {});
        t.start();
        t.join();
        assertThatThrownBy(t::start)
            .isInstanceOf(IllegalThreadStateException.class);
    }

    // ═══ TIMED_WAITING state (sleep) ═══
    @Test
    void timedWaiting_duringSleep() throws InterruptedException {
        Thread t = new Thread(() -> {
            try { Thread.sleep(5000); } catch (InterruptedException e) { }
        });
        t.start();
        Thread.sleep(100);  // let t enter sleep
        assertThat(t.getState()).isEqualTo(Thread.State.TIMED_WAITING);
        t.interrupt();  // wake it up
        t.join();
    }

    // ═══ WAITING state (wait) ═══
    @Test
    void waitingState_onWait() throws InterruptedException {
        Object lock = new Object();
        Thread t = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(); } catch (InterruptedException e) { }
            }
        });
        t.start();
        Thread.sleep(100);  // let t enter wait
        assertThat(t.getState()).isEqualTo(Thread.State.WAITING);
        synchronized (lock) { lock.notify(); }  // wake it up
        t.join();
    }

    // ═══ BLOCKED state (waiting for lock) ═══
    @Test
    void blockedState_waitingForLock() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch lockAcquired = new CountDownLatch(1);

        // Thread-1 holds the lock
        Thread holder = new Thread(() -> {
            synchronized (lock) {
                lockAcquired.countDown();
                try { Thread.sleep(5000); } catch (InterruptedException e) { }
            }
        });
        holder.start();
        lockAcquired.await();  // wait until holder has the lock

        // Thread-2 tries to acquire the SAME lock → BLOCKED
        Thread blocker = new Thread(() -> {
            synchronized (lock) { /* will wait here */ }
        });
        blocker.start();
        Thread.sleep(100);  // let blocker try to acquire lock

        assertThat(blocker.getState()).isEqualTo(Thread.State.BLOCKED);

        holder.interrupt();  // release holder
        holder.join();
        blocker.join();
    }

    // ═══ RUNNABLE state ═══
    @Test
    void runnableState_whileActive() throws InterruptedException {
        CountDownLatch started = new CountDownLatch(1);
        CountDownLatch canFinish = new CountDownLatch(1);

        Thread t = new Thread(() -> {
            started.countDown();
            while (canFinish.getCount() > 0) { /* busy loop → RUNNABLE */ }
        });
        t.start();
        started.await();

        assertThat(t.getState()).isEqualTo(Thread.State.RUNNABLE);
        canFinish.countDown();
        t.join();
    }
}
